Definition PFC_FRAME : Z := 2272.

Definition shw (x : Z) : Z := 8 * (sh x / 8).

Definition SHX0 : expr := EMd M_MUL (ELit 8) (EAlu ALU_SRL (EAlu ALU_ADD (EAlu ALU_SRL (EVar 11) (ELit 3)) (ELit 2147450880)) (ELit 3)).
Definition SHX3 : expr := EMd M_MUL (ELit 8) (EAlu ALU_SRL (EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 11) (ELit 3)) (ELit 3)) (ELit 2147450880)) (ELit 3)).

Lemma shw_arith : forall x, 0 <= x < 2 ^ 47 ->
